  ('archetype.dark_archive.psychic_duelist', 'Duelista Psíquico', 'Psychic Duelist', 'Duelista psíquico', 'Arquétipo de Dark Archive; requisitos e talentos individuais oficial de oficial.', 'Dark Archive archetype; individual prerequisites and feats pending review.', 'Arquetipo de Dark Archive; requisitos y dotes individuales pendientes de revisión.', NULL, NULL, '{}'::text[], 'common', 'legacy', 'Dark Archive (pré-Remaster)', 203, '{"feats":[],"needs_review":false}'::jsonb),
  ('archetype.dark_archive.mind_smith', 'Ferreiro da Mente', 'Mind Smith', 'Forjador mental', 'Arquétipo de Dark Archive; requisitos e talentos individuais oficial de oficial.', 'Dark Archive archetype; individual prerequisites and feats pending review.', 'Arquetipo de Dark Archive; requisitos y dotes individuales pendientes de revisión.', NULL, NULL, '{}'::text[], 'common', 'legacy', 'Dark Archive (pré-Remaster)', 204, '{"feats":[],"needs_review":false}'::jsonb),
