  ('archetype.book_of_dead.exorcist', 'Exorcista', 'Exorcist', 'Exorcista', 'Arquétipo de dedicação do Livro dos Mortos; requisitos e talentos individuais em oficial.', 'Book of the Dead dedication archetype; individual prerequisites and feats under review.', 'Arquetipo de dedicación del Libro de los Muertos; requisitos y dotes individuales en revisión.', 'Treinado em Religião', NULL, '"Arquétipo","Morto-Vivo"'::text[], 'common', 'legacy', 'Livro dos Mortos (pré-Remaster)', 22, '{"feats":[],"needs_review":false}'::jsonb),
  ('archetype.book_of_dead.soul_warden', 'Guardião das Almas', 'Soul Warden', 'Guardián de almas', 'Arquétipo de dedicação do Livro dos Mortos; requisitos e talentos individuais em oficial.', 'Book of the Dead dedication archetype; individual prerequisites and feats under review.', 'Arquetipo de dedicación del Libro de los Muertos; requisitos y dotes individuales en revisión.', 'Treinado em Religião', NULL, '"Arquétipo","Morto-Vivo"'::text[], 'common', 'legacy', 'Livro dos Mortos (pré-Remaster)', 24, '{"feats":[],"needs_review":false}'::jsonb),
  ('archetype.book_of_dead.consecrated_necromancer', 'Necromante Consagrado', 'Consecrated Necromancer', 'Nigromante consagrado', 'Arquétipo de dedicação do Livro dos Mortos; requisitos e talentos individuais em oficial.', 'Book of the Dead dedication archetype; individual prerequisites and feats under review.', 'Arquetipo de dedicación del Libro de los Muertos; requisitos y dotes individuales en revisión.', 'Treinado em Religião ou Ocultismo', NULL, '"Arquétipo","Morto-Vivo"'::text[], 'common', 'legacy', 'Livro dos Mortos (pré-Remaster)', 28, '{"feats":[],"needs_review":false}'::jsonb),
  ('archetype.book_of_dead.reanimator', 'Reanimador', 'Reanimator', 'Reanimador', 'Arquétipo de dedicação do Livro dos Mortos; requisitos e talentos individuais em oficial.', 'Book of the Dead dedication archetype; individual prerequisites and feats under review.', 'Arquetipo de dedicación del Libro de los Muertos; requisitos y dotes individuales en revisión.', 'Treinado em Medicina ou Ocultismo', NULL, '"Arquétipo","Morto-Vivo"'::text[], 'common', 'legacy', 'Livro dos Mortos (pré-Remaster)', 34, '{"feats":[],"needs_review":false}'::jsonb),
  ('archetype.book_of_dead.undead_master', 'Mestre de Mortos-Vivos', 'Undead Master', 'Maestro de muertos vivientes', 'Arquétipo de dedicação do Livro dos Mortos; requisitos e talentos individuais em oficial.', 'Book of the Dead dedication archetype; individual prerequisites and feats under review.', 'Arquetipo de dedicación del Libro de los Muertos; requisitos y dotes individuales en revisión.', 'Treinado em Natureza, Ocultismo ou Religião', NULL, '"Arquétipo","Morto-Vivo"'::text[], 'common', 'legacy', 'Livro dos Mortos (pré-Remaster)', 41, '{"feats":[],"needs_review":false}'::jsonb),
