values
  ('spell.rage_elements.wood.pollen_pods', 'Vagens de Pólen', 'Pollen Pods', 'Vainas de polen', 'Cultiva bulbos de madeira sensíveis ao movimento que liberam pólen venenoso quando ativados.', 'Rage of Elements wood spell: Pollen Pods. Full mechanical text pending review.', 'Conjuro de madera de Rage of Elements: Vainas de polen. El texto mecánico completo queda pendiente de revisión.', 7, '"arcane","primal"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 197, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.wood.rigid_form', 'Forma Rígida', 'Rigid Form', 'Forma rígida', 'Usa a rigidez da madeira para tentar neutralizar efeitos de polimorfia nocivos que tenham você como alvo.', 'Rage of Elements wood spell: Rigid Form. Full mechanical text pending review.', 'Conjuro de madera de Rage of Elements: Forma rígida. El texto mecánico completo queda pendiente de revisión.', 4, '"arcane","primal"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 197, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.wood.root_reading', 'Leitura de Raízes', 'Root Reading', 'Lectura de raíces', 'Percebe criaturas ocultas e rastros recentes ao enviar seus sentidos pelos sistemas de raízes da vegetação.', 'Rage of Elements wood spell: Root Reading. Full mechanical text pending review.', 'Conjuro de madera de Rage of Elements: Lectura de raíces. El texto mecánico completo queda pendiente de revisión.', 1, '"arcane","primal"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 198, '{"heightened":null,"needs_review":false}'::jsonb),
