  ('spell.rage_elements.wood.timber', 'Tronco', 'Timber', 'Tronco', 'Cria uma pequena árvore que cai em uma linha, causando dano contundente e podendo deixar criaturas ofuscadas.', 'Rage of Elements wood spell: Timber. Full mechanical text pending review.', 'Conjuro de madera de Rage of Elements: Tronco. El texto mecánico completo queda pendiente de revisión.', 1, '"arcane","primal"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 198, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.wood.verdant_sprout', 'Broto Verdejante', 'Verdant Sprout', 'Brote verdante', 'Planta uma semente que cresce em uma planta resistente, fornecendo cobertura, terreno difícil e alimento.', 'Rage of Elements wood spell: Verdant Sprout. Full mechanical text pending review.', 'Conjuro de madera de Rage of Elements: Brote verdante. El texto mecánico completo queda pendiente de revisión.', 1, '"primal"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 199, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.wood.wall_of_shrubs', 'Muralha de Arbustos', 'Wall of Shrubs', 'Muro de arbustos', 'Faz uma linha ou anel de arbustos surgir do chão para conceder cobertura na área.', 'Rage of Elements wood spell: Wall of Shrubs. Full mechanical text pending review.', 'Conjuro de madera de Rage of Elements: Muro de arbustos. El texto mecánico completo queda pendiente de revisión.', 1, '"arcane","primal"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 199, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.wood.weave_wood', 'Trançar Madeira', 'Weave Wood', 'Tejer madera', 'Transforma madeira, juncos ou fibras vegetais em vários objetos mundanos de madeira trançada.', 'Rage of Elements wood spell: Weave Wood. Full mechanical text pending review.', 'Conjuro de madera de Rage of Elements: Tejer madera. El texto mecánico completo queda pendiente de revisión.', 1, '"arcane","primal"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 199, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.wood.wooden_double', 'Duplo de Madeira', 'Wooden Double', 'Doble de madera', 'Cria um duplicado de madeira que recebe um golpe crítico no seu lugar e deixa você dar um passo.', 'Rage of Elements wood spell: Wooden Double. Full mechanical text pending review.', 'Conjuro de madera de Rage of Elements: Doble de madera. El texto mecánico completo queda pendiente de revisión.', 3, '"arcane","occult","primal"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 199, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.wood.wooden_fists', 'Punhos de Madeira', 'Wooden Fists', 'Puños de madera', 'Transforma seus punhos em troncos, concedendo ataques contundentes com alcance e melhorias em níveis elevados.', 'Rage of Elements wood spell: Wooden Fists. Full mechanical text pending review.', 'Conjuro de madera de Rage of Elements: Puños de madera. El texto mecánico completo queda pendiente de revisión.', 1, '"arcane","primal"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 199, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.wood.arms_of_nature', 'Braços da Natureza', 'Arms of Nature', 'Brazos de la naturaleza', 'Extrai uma arma de madeira de um objeto ou planta, com aprimoramentos conforme o nível.', 'Draws a wooden weapon from an object or plant, with upgrades at higher ranks.', 'Extrae un arma de madera de un objeto o planta, con mejoras en rangos superiores.', 1, '"divine"'::text[], 'two-actions', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 199, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.wood.wood_walk', 'Caminhar pela Madeira', 'Wood Walk', 'Caminar por la madera', 'Permite mover-se por plantas vivas e árvores próximas, inclusive em diferentes direções.', 'Lets you move along living plants and nearby trees, including in different directions.', 'Te permite moverte por plantas vivas y árboles cercanos, incluso en distintas direcciones.', 4, '"divine"'::text[], 'two-actions', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 199, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.practice_makes_perfect', 'A Prática Leva à Perfeição', 'Practice Makes Perfect', 'La práctica hace al maestro', 'Concede um bônus a um teste de perícia treinada que falhou.', 'Rage of Elements toil domain focus spell: Practice Makes Perfect. Full mechanical text pending review.', 'Conjuro de foco del dominio toil de Rage of Elements: La práctica hace al maestro. El texto mecánico completo queda pendiente de revisión.', 1, '"divine"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 97, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.earth.tireless_worker', 'Trabalhador Incansável', 'Tireless Worker', 'Trabajador incansable', 'Suprime temporariamente condições como desajeitado, sobrecarregado, enfraquecido ou fatigado.', 'Rage of Elements toil domain focus spell: Tireless Worker. Full mechanical text pending review.', 'Conjuro de foco del dominio toil de Rage of Elements: Trabajador incansable. El texto mecánico completo queda pendiente de revisión.', 4, '"divine"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 97, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.serrate', 'Serrar', 'Serrate', 'Serrar', 'Adiciona lâminas a uma arma metálica, causando dano cortante adicional até seu próximo turno.', 'Rage of Elements metal domain focus spell: Serrate. Full mechanical text pending review.', 'Conjuro de foco del dominio metal de Rage of Elements: Serrar. El texto mecánico completo queda pendiente de revisión.', 1, '"divine"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 145, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.rage_elements.metal.repel_metal', 'Repelir Metal', 'Repel Metal', 'Repeler metal', 'Protege contra um Golpe metálico e pode devolvê-lo ao atacante se errar.', 'Rage of Elements metal domain focus spell: Repel Metal. Full mechanical text pending review.', 'Conjuro de foco del dominio metal de Rage of Elements: Repeler metal. El texto mecánico completo queda pendiente de revisión.', 4, '"divine"'::text[], 'varies', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 145, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.howl.albatross_curse', 'Maldição do Albatroz', 'Albatross Curse', 'Maldición del albatros', 'Amaldiçoa uma criatura com azar e limita sua capacidade de voar ou se manter segura.', 'Curses a creature with misfortune and limits its ability to fly or remain safe.', 'Maldice a una criatura con infortunio y limita su capacidad de volar o mantenerse a salvo.', 2, '"occult","primal"'::text[], 'two-actions', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 85, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.howl.antlion_trap', 'Armadilha de Formigueiro-Leão', 'Antlion Trap', 'Trampa de hormiguero', 'Cria uma armadilha escavada que prende e pune criaturas que atravessam a área.', 'Creates a dug trap that restrains and punishes creatures crossing the area.', 'Crea una trampa excavada que retiene y castiga a las criaturas que cruzan el área.', 3, '"primal"'::text[], 'two-actions', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 85, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.howl.camel_spit', 'Cuspe de Camelo', 'Camel Spit', 'Escupitajo de camello', 'Lança um jato corrosivo de cuspe contra um alvo distante.', 'Projects a corrosive spit attack at a distant target.', 'Proyecta un ataque de saliva corrosiva contra un objetivo distante.', 1, '"arcane","primal"'::text[], 'two-actions', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 85, '{"heightened":null,"needs_review":false}'::jsonb),
  ('spell.howl.claws_of_the_otter', 'Garras da Lontra', 'Claws of the Otter', 'Garras de la nutria', 'Concede garras e adaptações de lontra para lutar e se mover na água.', 'Grants otter claws and adaptations for fighting and moving through water.', 'Concede garras y adaptaciones de nutria para luchar y moverse en el agua.', 2, '"divine","primal"'::text[], 'two-actions', NULL, NULL, NULL, NULL, '{}'::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 85, '{"heightened":null,"needs_review":false}'::jsonb),
