values
  ('ritual.animate_object', 'Animar Objeto', 'Animate Object', 'Animar objeto', 'Transforma um objeto em uma criatura animada; um resultado superior pode permitir controlá-la como lacaio.', 'Transforms an object into an animated creature; a superior result can allow it to be controlled as a minion.', 'Transforma un objeto en una criatura animada; un resultado superior puede permitir controlarla como esbirro.', 2, '1 dia', NULL, 0, '{}'::text[], '{}'::text[], 'uncommon', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 390, '{"cost":null,"needs_review":false}'::jsonb),
  ('ritual.rune_trap', 'Armadilha Rúnica', 'Rune Trap', 'Trampa rúnica', 'Vincula uma magia hostil a uma runa ativada por senha, acionamento ou aproximação.', 'Binds a hostile spell to a rune activated by a password, trigger, or approach.', 'Vincula un conjuro hostil a una runa activada por contraseña, desencadenante o aproximación.', 3, '1 dia', NULL, 0, '{}'::text[], '{}'::text[], 'uncommon', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 390, '{"cost":null,"needs_review":false}'::jsonb),
  ('ritual.call_spirit', 'Chamar Espírito', 'Call Spirit', 'Llamar espíritu', 'Chama pelo nome um espírito do além para uma conversa breve, usando uma conexão pessoal com ele.', 'Calls a named spirit from the afterlife for a brief conversation using a personal connection to it.', 'Llama por su nombre a un espíritu del más allá para una conversación breve usando una conexión personal.', 5, '1 dia', NULL, 0, '{}'::text[], '{}'::text[], 'uncommon', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 391, '{"cost":null,"needs_review":false}'::jsonb),
  ('ritual.consecrate', 'Consagrar', 'Consecrate', 'Consagrar', 'Dedica um local a uma divindade, favorecendo seus adoradores e dificultando a ação de criaturas anátema.', 'Dedicates a site to a deity, favoring worshippers and hindering creatures that are anathema to that deity.', 'Dedica un lugar a una deidad, favorece a sus fieles y dificulta la acción de criaturas anatema.', 2, '1 dia', NULL, 0, '{}'::text[], '{}'::text[], 'uncommon', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 392, '{"cost":null,"needs_review":false}'::jsonb),
  ('ritual.rage_elements.bountiful_oasis', 'Oásis Abundante', 'Bountiful Oasis', 'Oasis abundante', 'Redireciona água subterrânea para criar uma fonte ou oásis que sustenta uma pequena comunidade.', 'Redirects underground water to create a spring or oasis capable of supporting a small community.', 'Redirige agua subterránea para crear un manantial u oasis capaz de sostener una pequeña comunidad.', 5, '1 dia', NULL, 0, '{}'::text[], '{}'::text[], 'uncommon', 'remaster', 'Rage of Elements (Remaster)', 175, '{"cost":null,"needs_review":false}'::jsonb),
