insert into public.catalog_pets (id, name_pt, name_en, name_es, description_pt, description_en, description_es, pet_type, size, speed_feet, hp_base, support_benefit, advanced_maneuver, traits, ruleset, source_book, source_page, data)
values
  ('pet.wolf', 'Lobo', 'Wolf Companion', 'Compañero lobo', 'Companheiro veloz que ajuda a flanquear e derrubar inimigos.', 'Fast companion that helps flank and trip enemies.', 'Compañero veloz que ayuda a flanquear y derribar enemigos.', 'animal_companion', 'Pequeno ou Médio', 30, 6, NULL, NULL, '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"attacks":"Mandíbulas: 1d8 perfuração (Ágil, Derrubar)","needs_review":false}'::jsonb),
  ('pet.bear', 'Urso', 'Bear Companion', 'Compañero oso', 'Companheiro resistente com mordidas e garras poderosas.', 'Durable companion with powerful jaws and claws.', 'Compañero resistente con poderosas mordidas y garras.', 'animal_companion', 'Pequeno ou Médio', 30, 8, NULL, NULL, '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"attacks":"Garras: 1d8 cortante (Ágil), Mandíbulas: 1d8 perfuração","needs_review":false}'::jsonb),
  ('pet.horse', 'Cavalo', 'Horse Companion / Mount', 'Compañero caballo / Montura', 'Montaria veloz para investidas e combate montado.', 'Fast mount for charges and mounted combat.', 'Montura veloz para cargas y combate montado.', 'animal_companion', 'Grande', 30, 8, NULL, NULL, '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"attacks":"Cascos: 1d6 impacto (Ágil)","needs_review":false}'::jsonb),
  ('pet.bird', 'Pássaro / Coruja', 'Bird Companion', 'Compañero ave', 'Companheiro voador ágil para reconhecimento e ataques precisos.', 'Agile flying companion for scouting and precise attacks.', 'Compañero volador ágil para explorar y atacar con precisión.', 'animal_companion', 'Pequeno', 30, 4, NULL, NULL, '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"attacks":"Garras: 1d6 cortante (Ágil, Acabamento)","needs_review":false}'::jsonb),
  ('pet.big_cat', 'Gato Grande / Pantera', 'Big Cat', 'Gran felino / Pantera', 'Companheiro furtivo que ajuda a deixar inimigos desprevenidos.', 'Stealthy companion that helps leave enemies off-guard.', 'Compañero sigiloso que ayuda a dejar desprevenidos a los enemigos.', 'animal_companion', 'Pequeno ou Médio', 30, 6, NULL, NULL, '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"attacks":"Garras: 1d6 cortante (Ágil), Mordida: 1d8 perfuração","needs_review":false}'::jsonb),
  ('pet.dromaeosaur', 'Dromaeossauro', 'Dromaeosaur Companion', 'Compañero dromeosaurio', 'Companheiro veloz especializado em cercar e flanquear inimigos.', 'Fast companion specialized in surrounding and flanking enemies.', 'Compañero veloz especializado en rodear y flanquear enemigos.', 'animal_companion', 'Pequeno', 30, 6, NULL, NULL, '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 207, '{"attacks":"Garras: 1d8 cortante (Ágil, Flanquear)","needs_review":false}'::jsonb),
  ('pet.badger', 'Texugo', 'Badger Companion', 'Compañero tejón', 'Companheiro resistente que cava e causa dano contínuo.', 'Sturdy companion that burrows and deals persistent damage.', 'Compañero resistente que excava y causa daño persistente.', 'animal_companion', 'Pequeno', 30, 8, NULL, NULL, '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 206, '{"attacks":"Garras: 1d8 cortante (Ágil)","needs_review":false}'::jsonb),
  ('pet.familiar', 'Familiar Arcano / Místico', 'Familiar', 'Familiar arcano / místico', 'Familiar que concede habilidades escolhidas ao seu mestre.', 'A familiar that grants chosen abilities to its master.', 'Familiar que concede habilidades elegidas a su amo.', 'animal_companion', 'Minúsculo', 30, 5, NULL, NULL, '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 212, '{"attacks":"Sem ataque próprio","needs_review":false}'::jsonb),
  ('pet.howl.antelope', 'Antílope', 'Antelope', 'Antílope', 'Companheiro veloz e montável que pode causar sangramento persistente.', 'A swift mount companion that can cause persistent bleed damage.', 'Compañero veloz y montable que puede causar daño persistente por sangrado.', 'animal_companion', 'Médio ou Grande', 30, 6, 'Enquanto montado, Golpes que causam dano no alcance do antílope também causam 1d6 de sangramento persistente até o início do seu próximo turno.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 91, '{"attacks":[{"name":"Chifres","bonus":"—","damage":"1d6 perfurante","traits":["Acurada"]},{"name":"Casco","bonus":"—","damage":"1d4 impacto","traits":["Ágil","Acurada"]}],"needs_review":false}'::jsonb),
  ('pet.howl.elk', 'Alce', 'Elk', 'Alce', 'Companheiro montável que intimida inimigos com seus chifres.', 'A mount companion that frightens enemies with its antlers.', 'Compañero montable que asusta a los enemigos con sus astas.', 'animal_companion', 'Médio ou Grande', 30, 8, 'Até o início do seu próximo turno, se você atingir e causar dano a uma criatura no alcance do alce, ela fica Amedrontada 1.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 91, '{"attacks":[{"name":"Chifres","bonus":"—","damage":"1d8 perfurante","traits":[]},{"name":"Casco","bonus":"—","damage":"1d6 impacto","traits":["Ágil"]}],"needs_review":false}'::jsonb),
  ('pet.howl.flying_squirrel', 'Esquilo Voador', 'Flying Squirrel', 'Ardilla voladora', 'Companheiro que plana e dificulta o deslocamento dos inimigos.', 'A companion that glides and hampers enemy movement.', 'Compañero que planea y dificulta el movimiento enemigo.', 'animal_companion', 'Pequeno', 30, 6, 'Até o fim do seu próximo turno, um alvo atingido por seu Golpe no alcance do esquilo sofre –10 pés de penalidade de circunstância em seus Deslocamentos por 1 rodada.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 92, '{"attacks":[{"name":"Mandíbulas","bonus":"—","damage":"1d6 perfurante","traits":["Acurada"]},{"name":"Garra","bonus":"—","damage":"1d4 cortante","traits":["Ágil","Acurada"]}],"needs_review":false}'::jsonb),
  ('pet.howl.giraffe', 'Girafa', 'Giraffe', 'Jirafa', 'Companheiro montável de pescoço longo que amplia manobras de Empurrar.', 'A long-necked mount that improves Shove maneuvers.', 'Montura de cuello largo que mejora las maniobras de Empujar.', 'animal_companion', 'Grande', 30, 8, 'Enquanto montado na girafa, você não precisa de uma mão livre para Empurrar e um inimigo Empurrado move 10 pés (15 pés em sucesso crítico).', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 92, '{"attacks":[{"name":"Casco","bonus":"—","damage":"1d6 impacto","traits":["Ágil"]},{"name":"Pescoço","bonus":"—","damage":"1d4 impacto","traits":["Não-Letal","Alcance 10 pés"]}],"needs_review":false}'::jsonb),
  ('pet.howl.kangaroo', 'Canguru', 'Kangaroo', 'Canguro', 'Companheiro saltador que combina mobilidade e ataques corporais.', 'A leaping companion combining mobility and natural attacks.', 'Compañero saltador que combina movilidad y ataques naturales.', 'animal_companion', 'Pequeno', 30, 6, 'Até o início do seu próximo turno, o canguru conta como estando em seu espaço ou em um espaço vazio a até 5 pés para determinar flanqueamento.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 92, '{"attacks":[{"name":"Pé","bonus":"—","damage":"1d6 impacto","traits":["Ágil"]}],"needs_review":false}'::jsonb),
  ('pet.howl.mongoose', 'Mangusto', 'Mongoose', 'Mangosta', 'Companheiro ágil que protege criaturas próximas contra flanqueamento.', 'An agile companion that protects nearby creatures from flanking.', 'Compañero ágil que protege a criaturas cercanas contra el flanqueo.', 'animal_companion', 'Pequeno', 30, 4, 'Até o fim do seu próximo turno, criaturas adjacentes ao mangusto não podem flanquear você.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 93, '{"attacks":[{"name":"Mandíbulas","bonus":"—","damage":"1d6 perfurante","traits":["Acurada"]},{"name":"Garra","bonus":"—","damage":"1d4 cortante","traits":["Ágil","Acurada"]}],"needs_review":false}'::jsonb),
  ('pet.howl.salamander', 'Salamandra', 'Salamander', 'Salamandra', 'Companheiro anfíbio que secreta veneno e nada em águas rasas.', 'An amphibious companion that secretes poison and swims in shallow water.', 'Compañero anfibio que secreta veneno y nada en aguas poco profundas.', 'animal_companion', 'Pequeno', 30, 6, 'Até o início do seu próximo turno, uma criatura adjacente que atingir você ou a salamandra sofre 1d6 de dano de veneno.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 93, '{"attacks":[{"name":"Cauda","bonus":"—","damage":"1d6 impacto","traits":[]},{"name":"Mandíbulas","bonus":"—","damage":"1d4 perfurante","traits":[]}],"needs_review":false}'::jsonb),
  ('pet.howl.giant_eel', 'Enguia Gigante', 'Giant Eel', 'Anguila gigante', 'Companheiro aquático avançado que cria ângulos inesperados para flanquear.', 'An advanced aquatic companion that creates unexpected flanking positions.', 'Compañero acuático avanzado que crea posiciones inesperadas de flanqueo.', 'animal_companion', 'Grande', 30, 4, 'Até o início do seu próximo turno, para determinar flanqueamento a enguia pode contar como estando em seu espaço ou em um espaço vazio a até 10 pés, escolhendo um espaço diferente a cada ataque.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 94, '{"attacks":[{"name":"Mandíbulas","bonus":"—","damage":"1d8 perfurante","traits":[]}],"needs_review":false}'::jsonb),
  ('pet.howl.giant_frog', 'Sapo Gigante', 'Giant Frog', 'Rana gigante', 'Companheiro anfíbio avançado com língua de longo alcance e controle de reações.', 'An advanced amphibious companion with a long-range tongue and reaction control.', 'Compañero anfibio avanzado con lengua de largo alcance y control de reacciones.', 'animal_companion', 'Grande', 30, 6, 'Até o início do seu próximo turno, quando você atingir com sucesso uma criatura ameaçada pelo sapo, ela não pode usar reações acionadas por suas ações, a menos que seu nível seja maior que o seu.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 94, '{"attacks":[{"name":"Mandíbulas","bonus":"—","damage":"1d8 perfurante","traits":[]},{"name":"Língua","bonus":"—","damage":"1d4 impacto","traits":["Alcance 15 pés"]}],"needs_review":false}'::jsonb),
  ('pet.howl.hippogriff', 'Hipogrifo', 'Hippogriff', 'Hipogrifo', 'Companheiro voador avançado para montaria e ataques aéreos.', 'An advanced flying companion for mounted and aerial attacks.', 'Compañero volador avanzado para ataques montados y aéreos.', 'animal_companion', 'Grande', 30, 8, 'Enquanto montado e após mover-se 10 pés ou mais antes de um Golpe corpo a corpo, adicione ao dano um bônus de circunstância igual ao dobro dos dados de dano da arma.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 95, '{"attacks":[{"name":"Bico","bonus":"—","damage":"1d6 perfurante","traits":[]},{"name":"Garra","bonus":"—","damage":"1d4 cortante","traits":["Ágil"]}],"needs_review":false}'::jsonb),
  ('pet.howl.riding_tarantula', 'Tarântula de Montaria', 'Riding Tarantula', 'Tarántula de monta', 'Companheiro aracnídeo avançado que escala e perturba ações de concentração.', 'An advanced arachnid companion that climbs and disrupts concentrate actions.', 'Compañero arácnido avanzado que trepa y perturba acciones de concentración.', 'animal_companion', 'Grande', 30, 4, 'Até o início do seu próximo turno, uma criatura atingida por seu Golpe que esteja no alcance da tarântula deve passar em um teste simples CD 5 ao usar uma ação de concentração ou perde a ação.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 96, '{"attacks":[{"name":"Presas","bonus":"—","damage":"1d6 perfurante mais veneno","traits":["Acurada"]},{"name":"Perna","bonus":"—","damage":"1d4 perfurante","traits":["Ágil","Acurada"]}],"needs_review":false}'::jsonb),
  ('pet.howl.roc', 'Roc', 'Roc', 'Roc', 'Companheiro voador colossal avançado capaz de carregar criaturas e empurrá-las.', 'A colossal advanced flying companion able to carry and push creatures.', 'Compañero volador colosal avanzado capaz de transportar y empujar criaturas.', 'animal_companion', 'Enorme', 30, 8, 'Até o início do seu próximo turno, seus Golpes que causam dano a uma criatura ameaçada pelo roc empurram o alvo 5 pés para longe do roc.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 96, '{"attacks":[{"name":"Bico","bonus":"—","damage":"1d10 perfurante","traits":[]},{"name":"Garra","bonus":"—","damage":"1d8 cortante mais Agarrar","traits":["Ágil"]}],"needs_review":false}'::jsonb),
  ('pet.howl.umbrella_mushroom', 'Cogumelo Guarda-Chuva', 'Umbrella Mushroom', 'Hongo sombrilla', 'Companheiro fungo avançado que flutua e deixa inimigos estupefatos.', 'An advanced fungal companion that floats and leaves enemies stupefied.', 'Compañero fúngico avanzado que flota y deja a los enemigos estupefactos.', 'animal_companion', 'Grande', 30, 6, 'Até o início do seu próximo turno, seus Golpes que causam dano a uma criatura no alcance do cogumelo deixam o alvo Estupefato 1 por 1 rodada; o efeito tem o traço veneno.', NULL, '{}'::text[], 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 96, '{"attacks":[{"name":"Haste","bonus":"—","damage":"1d8 impacto","traits":[]}],"needs_review":false}'::jsonb),
  ('pet.eidolon.devotion_abomination', 'Abantesma da Devoção', 'Devotion Phantom', 'Abantesma de devoción', 'Eidolon ocultista ligado à devoção e à proteção espiritual.', 'An occult eidolon tied to devotion and spiritual protection.', 'Eidolon ocultista ligado a la devoción y la protección espiritual.', 'eidolon', 'Médio,Pequeno', 7.5, 8, NULL, NULL, '"abantesma","eidolon","etéreo"'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 43, '{"attacks":[],"needs_review":false}'::jsonb),
  ('pet.eidolon.rage_abomination', 'Abantesma da Raiva', 'Rage Phantom', 'Abantesma de ira', 'Abantesma ocultista movido por fúria e emoções intensas.', 'An occult eidolon driven by rage and intense emotion.', 'Eidolon ocultista impulsado por la ira y emociones intensas.', 'eidolon', 'Médio,Pequeno', 7.5, 8, NULL, NULL, '"abantesma","eidolon","etéreo"'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 43, '{"attacks":[],"needs_review":false}'::jsonb),
  ('pet.eidolon.angel', 'Anjo', 'Angel', 'Ángel', 'Eidolon divino formado por essência celestial e poder de cura.', 'A divine eidolon formed from celestial essence and healing power.', 'Un eidolon divino formado de esencia celestial y poder curativo.', 'eidolon', 'Médio,Pequeno', 7.5, 8, NULL, NULL, '"anjo","celestial","eidolon"'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 43, '{"attacks":[],"needs_review":false}'::jsonb),
  ('pet.eidolon.beast', 'Besta', 'Beast', 'Bestia', 'Eidolon primal de forma animal, adaptável a combate e exploração.', 'A primal animal eidolon adaptable to combat and exploration.', 'Un eidolon primal de forma animal, adaptable al combate y la exploración.', 'eidolon', 'Médio', 7.5, 8, NULL, NULL, '"besta","eidolon"'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 43, '{"attacks":[],"needs_review":false}'::jsonb),
  ('pet.eidolon.construct', 'Constructo', 'Construct', 'Constructo', 'Eidolon arcano construído com matéria e magia vinculadas ao convocador.', 'An arcane eidolon built from matter and magic bound to its summoner.', 'Un eidolon arcano construido con materia y magia vinculadas a su convocador.', 'eidolon', 'Médio', 7.5, 8, NULL, NULL, '"astral","construct","eidolon"'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 43, '{"attacks":[],"needs_review":false}'::jsonb),
  ('pet.eidolon.demon', 'Demônio', 'Demon', 'Demonio', 'Eidolon divino de essência demoníaca e impulsos destrutivos.', 'A divine eidolon of demonic essence and destructive impulses.', 'Un eidolon divino de esencia demoníaca e impulsos destructivos.', 'eidolon', 'Médio,Pequeno', 7.5, 8, NULL, NULL, '"demônio","eidolon","ínfero"'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 43, '{"attacks":[],"needs_review":false}'::jsonb),
  ('pet.eidolon.dragon', 'Dragão', 'Dragon', 'Dragón', 'Eidolon arcano que manifesta a herança e o poder de um dragão.', 'An arcane eidolon manifesting draconic heritage and power.', 'Un eidolon arcano que manifiesta herencia y poder dracónicos.', 'eidolon', 'Médio', 7.5, 8, NULL, NULL, '"astral","dragão","eidolon"'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 43, '{"attacks":[],"needs_review":false}'::jsonb),
  ('pet.eidolon.fey', 'Fada', 'Fey', 'Hada', 'Eidolon primal de essência feérica, astuto e conectado à natureza.', 'A primal eidolon of fey essence, cunning and connected to nature.', 'Un eidolon primal de esencia feérica, astuto y conectado con la naturaleza.', 'eidolon', 'Pequeno,Médio', 7.5, 8, NULL, NULL, '"eidolon","fada"'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 43, '{"attacks":[],"needs_review":false}'::jsonb),
  ('pet.eidolon.plant', 'Planta', 'Plant', 'Planta', 'Eidolon primal de matéria vegetal e vitalidade natural.', 'A primal eidolon of plant matter and natural vitality.', 'Un eidolon primal de materia vegetal y vitalidad natural.', 'eidolon', 'Médio', 7.5, 8, NULL, NULL, '"eidolon","planta"'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 43, '{"attacks":[],"needs_review":false}'::jsonb),
  ('pet.eidolon.psychopomp', 'Psicopompo', 'Psychopomp', 'Psicopompo', 'Eidolon ocultista ligado ao ciclo das almas e à passagem dos mortos.', 'An occult eidolon tied to the cycle of souls and passage of the dead.', 'Un eidolon ocultista ligado al ciclo de las almas y al tránsito de los muertos.', 'eidolon', 'Médio', 7.5, 8, NULL, NULL, '"eidolon","monitor","psicopompo"'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 43, '{"attacks":[],"needs_review":false}'::jsonb)
insert into public.catalog_actions (id, name_pt, name_en, name_es, description_pt, description_en, description_es, action_type, category, traits, ruleset, source_book, source_page, data)
values
  ('action.strike', 'Golpear', 'Strike', 'Golpear', 'Você ataca com uma arma que está empunhando ou com um ataque desarmado.', 'Core action: Strike.', 'Acción básica: Golpear.', 'one-action', 'Ações Básicas', '"Ataque"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 419, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.stride', 'Andar', 'Stride', 'Avanzar', 'Você se move a uma distância de até o seu deslocamento terrestre.', 'Core action: Stride.', 'Acción básica: Avanzar.', 'one-action', 'Ações Básicas', '"Movimento"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 419, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.step', 'Dar um Passo', 'Step', 'Paso', 'Você se move cuidadosamente 1,5 metro sem acionar reações baseadas em movimento (como Ataque de Oportunidade).', 'Core action: Step.', 'Acción básica: Paso.', 'one-action', 'Ações Básicas', '"Movimento"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 419, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.raise_shield', 'Erguer Escudo', 'Raise a Shield', 'Levantar un escudo', 'Você posiciona seu escudo para se proteger, recebendo o bônus de circunstância na CA até o início do seu próximo turno.', 'Core action: Raise a Shield.', 'Acción básica: Levantar un escudo.', 'one-action', 'Ações Básicas', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 419, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.take_cover', 'Pegar Cobertura', 'Take Cover', 'Buscar cobertura', 'Você se abaixa ou se esconde atrás de um obstáculo, melhorando sua cobertura para padrão (+2 CA) ou maior (+4 CA).', 'Core action: Take Cover.', 'Acción básica: Buscar cobertura.', 'one-action', 'Ações Básicas', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 419, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.interact', 'Interagir', 'Interact', 'Interactuar', 'Você saca uma arma, guarda um item, abre uma porta ou pega um objeto do chão.', 'Core action: Interact.', 'Acción básica: Interactuar.', 'one-action', 'Ações Básicas', '"Manipular"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 419, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.escape', 'Escapar', 'Escape', 'Escapar', 'Você tenta se libertar de um efeito que o imobilizou, agarrou ou restringiu com Atletismo, Acrobacia ou Ataque Desarmado.', 'Core action: Escape.', 'Acción básica: Escapar.', 'one-action', 'Ações Básicas', '"Ataque"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 418, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.leap', 'Saltar', 'Leap', 'Saltar', 'Você dá um salto curto horizontal de até 3m ou vertical de até 0,9m.', 'Core action: Leap.', 'Acción básica: Saltar.', 'one-action', 'Ações Básicas', '"Movimento"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 418, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.trip', 'Derrubar', 'Trip', 'Derribo', 'Faça um teste de Atletismo contra a CD de Reflexos do alvo para deixá-lo Caído.', 'Core action: Trip.', 'Acción básica: Derribo.', 'one-action', 'Manobras de Combate', '"Ataque"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 236, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.grapple', 'Agarrar', 'Grapple', 'Agarrar', 'Faça um teste de Atletismo contra a CD de Fortitude do alvo para deixá-lo Agarrado ou Restringido.', 'Core action: Grapple.', 'Acción básica: Agarrar.', 'one-action', 'Manobras de Combate', '"Ataque"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 235, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.shove', 'Empurrar', 'Shove', 'Empujar', 'Faça um teste de Atletismo contra a CD de Fortitude do alvo para empurrá-lo 1,5m ou mais para longe.', 'Core action: Shove.', 'Acción básica: Empujar.', 'one-action', 'Manobras de Combate', '"Ataque"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 236, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.disarm', 'Desarmar', 'Disarm', 'Desarmar', 'Faça um teste de Atletismo contra a CD de Reflexos do alvo para afrouxar a empunhadura dele ou derrubar a arma.', 'Core action: Disarm.', 'Acción básica: Desarmar.', 'one-action', 'Manobras de Combate', '"Ataque"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 235, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.feint', 'Fintar', 'Feint', 'Fintar', 'Faça um teste de Enganação contra a CD de Percepção do alvo para deixá-lo Desprevenido contra seu próximo ataque.', 'Core action: Feint.', 'Acción básica: Fintar.', 'one-action', 'Perícias em Combate', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 239, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.demoralize', 'Desmoralizar', 'Demoralize', 'Desmoralizar', 'Faça um teste de Intimidação contra a CD de Vontade do alvo para deixá-lo Amedrontado 1 (ou 2 no crítico).', 'Core action: Demoralize.', 'Acción básica: Desmoralizar.', 'one-action', 'Perícias em Combate', '"Auditivo","Concentração","Emoção","Mental"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 241, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.treat_wounds', 'Tratar Ferimentos', 'Treat Wounds', 'Tratar heridas', 'Gaste 10 minutos tratando uma criatura ferida. No sucesso, restaura 2d8 PV (CD 15) ou mais em CDs superiores.', 'Core action: Treat Wounds.', 'Acción básica: Tratar heridas.', 'activity', 'Medicina', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 242, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.battle_medicine', 'Medicina de Batalha', 'Battle Medicine', 'Medicina de batalla', 'Em combate, use Tratar Ferimentos instantaneamente em 1 ação para restaurar PV de um aliado adjacente.', 'Core action: Battle Medicine.', 'Acción básica: Medicina de batalla.', 'one-action', 'Medicina', '"Cura","Manipular"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 254, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.recall_knowledge', 'Recordar Conhecimento', 'Recall Knowledge', 'Recordar conocimiento', 'Faça um teste de perícia correspondente (Arcanismo, Natureza, Ocultismo, Religião, Sociedade ou Saber) para identificar fraquezas ou segredos.', 'Core action: Recall Knowledge.', 'Acción básica: Recordar conocimiento.', 'one-action', 'Conhecimento', '"Concentração"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 231, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.seek', 'Procurar', 'Seek', 'Buscar', 'Faça um teste de Percepção contra a CD de Furtividade de criaturas ou para localizar armadilhas e portas ocultas.', 'Core action: Seek.', 'Acción básica: Buscar.', 'one-action', 'Percepção', '"Concentração","Segredo"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 420, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.hide', 'Esconder-se', 'Hide', 'Esconderse', 'Faça um teste de Furtividade contra a CD de Percepção dos observadores para se tornar Oculto.', 'Core action: Hide.', 'Acción básica: Esconderse.', 'one-action', 'Furtividade', '"Segredo"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 244, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.sneak', 'Esgueirar-se', 'Sneak', 'Escabullirse', 'Mova-se a até metade do seu deslocamento permanecendo Indetectado.', 'Core action: Sneak.', 'Acción básica: Escabullirse.', 'one-action', 'Furtividade', '"Movimento","Segredo"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 245, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.avoid_notice', 'Evitar Atenção', 'Avoid Notice', 'Evitar ser detectado', 'Atividade de exploração onde você se move com cautela furtiva e rola Furtividade para iniciativa.', 'Core action: Avoid Notice.', 'Acción básica: Evitar ser detectado.', 'activity', 'Exploração', '"Exploração"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 438, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.defend', 'Defender', 'Defend', 'Defender', 'Atividade de exploração onde você caminha com escudo erguido, iniciando o combate com bônus de CA.', 'Core action: Defend.', 'Acción básica: Defender.', 'activity', 'Exploração', '"Exploração"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 438, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.detect_magic', 'Detectar Magia', 'Detect Magic', 'Detectar magia', 'Atividade de exploração onde você conjura continuamente Detectar Magia ao avançar pela masmorra.', 'Core action: Detect Magic.', 'Acción básica: Detectar magia.', 'activity', 'Exploração', '"Exploração"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 438, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb),
  ('action.scout', 'Batedor', 'Scout', 'Explorar', 'Atividade de exploração onde você antecipa perigos, concedendo +1 de bônus na iniciativa de todos os aliados.', 'Core action: Scout.', 'Acción básica: Explorar.', 'activity', 'Exploração', '"Exploração"'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 438, '{"trigger":null,"requirements":null,"needs_review":false}'::jsonb)
